-- PostgreSQL twin of migrations/0083_vambi_metrics.sql, generated by scripts/sqlite_to_pg_migration.py
-- (hand fix: vambi_order_attributions.order_id is a plain BIGINT key referencing orders, not a serial)

-- Vambi launch metrics (سنجش استفادهٔ وامبی), section 6 of docs/vambi-comms-plan.md. First-party only.
-- Daily counters hold a number per Tehran day and metric — no query text, no user id, no IP.
CREATE TABLE IF NOT EXISTS vambi_daily_counts (
    day     TEXT    NOT NULL,
    metric  TEXT    NOT NULL CHECK (metric IN ('search', 'buy_click')),
    n       INTEGER NOT NULL DEFAULT 0 CHECK (n >= 0),
    PRIMARY KEY (day, metric)
);

-- A signed-in buyer who arrived from a Vambi «مشاهده و خرید» link (?ref=vambi), reported through the existing
-- referral capture (POST /api/v1/me/referral with code "vambi"). Valid for 7 days, like an affiliate referral.
CREATE TABLE IF NOT EXISTS vambi_referrals (
    id          BIGSERIAL PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    landed_at   TEXT    NOT NULL,
    expires_at  TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_vambi_referrals_user ON vambi_referrals(user_id, landed_at);

-- An order placed while its buyer had a live Vambi referral; written once at order creation.
CREATE TABLE IF NOT EXISTS vambi_order_attributions (
    order_id    BIGINT  PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE,
    referral_id INTEGER REFERENCES vambi_referrals(id) ON DELETE SET NULL,
    created_at  TEXT    NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_vambi_order_attributions_created ON vambi_order_attributions(created_at);
